#include "s61_binary_deeper_quartic_field_20261101.hpp"
#include <array>
#include <chrono>
fmpq_mpoly_ctx_t c9;using Mon=array<int,7>;
void lift(fmpq_mpoly_t out,const fmpq_mpoly_t in){fmpq_mpoly_zero(out,c9);fmpq_t c;fmpq_init(c);ulong m[2],n[9]{};for(int k=0;k<fmpq_mpoly_length(in,ctx);k++){fmpq_mpoly_get_term_exp_ui(m,in,k,ctx);n[0]=m[0];n[1]=m[1];fmpq_mpoly_get_term_coeff_fmpq(c,in,k,ctx);fmpq_mpoly_push_term_fmpq_ui(out,c,n,c9);}fmpq_mpoly_sort_terms(out,c9);fmpq_mpoly_combine_like_terms(out,c9);fmpq_clear(c);}
void read9(istream&in,fmpq_mpoly_t p){int nn;in>>nn;fmpq_t c;fmpq_init(c);ulong m[9];for(int i=0;i<nn;i++){string v;in>>v;assert(fmpq_set_str(c,v.c_str(),10)==0);fmpq_canonicalise(c);for(auto&x:m)in>>x;fmpq_mpoly_push_term_fmpq_ui(p,c,m,c9);}fmpq_mpoly_sort_terms(p,c9);fmpq_mpoly_combine_like_terms(p,c9);fmpq_clear(c);}
void read16(istream&in,fmpq_mpoly_t p,bool den){long nn;in>>nn;fmpq_t c;fmpq_init(c);ulong m[16],n[9];int keep[7]={0,1,2,3,4,6,8};for(long i=0;i<nn;i++){string v;in>>v;assert(fmpq_set_str(c,v.c_str(),10)==0);fmpq_canonicalise(c);for(auto&x:m)in>>x;for(int j=2;j<7;j++)assert(m[j]==0);assert(m[12]==0&&m[14]==0);if(!den){assert(m[7]);m[7]--;}n[0]=m[0];n[1]=m[1];for(int j=0;j<7;j++){n[j+2]=m[keep[j]+7];if(den)assert(n[j+2]==0);}fmpq_mpoly_push_term_fmpq_ui(p,c,n,c9);}fmpq_mpoly_sort_terms(p,c9);fmpq_mpoly_combine_like_terms(p,c9);fmpq_clear(c);}
void unlift(fmpq_mpoly_t out,const fmpq_mpoly_t in){fmpq_mpoly_zero(out,ctx);fmpq_t c;fmpq_init(c);ulong m[9],n[2];for(int k=0;k<fmpq_mpoly_length(in,c9);k++){fmpq_mpoly_get_term_exp_ui(m,in,k,c9);for(int j=2;j<9;j++)assert(m[j]==0);n[0]=m[0];n[1]=m[1];fmpq_mpoly_get_term_coeff_fmpq(c,in,k,c9);fmpq_mpoly_push_term_fmpq_ui(out,c,n,ctx);}fmpq_mpoly_sort_terms(out,ctx);fmpq_mpoly_combine_like_terms(out,ctx);fmpq_clear(c);}
int main(int argc,char**argv){assert(argc==5);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);fmpq_mpoly_ctx_init(c9,9,ORD_LEX);{ifstream in(argv[1]),co(argv[2]),qi(argv[3]);ofstream out(argv[4]);int nr,nc;in>>nr>>nc;assert(nr==56&&nc==84);vector<Row>old(7);for(int i=0;i<56;i++){int n;in>>n;for(int j=0;j<n;j++){int k;in>>k;Rat c;readpoly(in,c.n);readpoly(in,c.d);if(i>=49)old[i-49].emplace(k,std::move(c));}}
vector<Mon>oldmons;for(int a=0;a<=3;a++)for(int b=0;b<=3-a;b++)for(int c=0;c<=3-a-b;c++)for(int d=0;d<=3-a-b-c;d++)for(int e=0;e<=3-a-b-c-d;e++)for(int f=0;f<=3-a-b-c-d-e;f++){int g=3-a-b-c-d-e-f;oldmons.push_back({a,b,c,d,e,f,g});}assert(oldmons.size()==84);map<Mon,int>index;int count=0;for(int a=0;a<7;a++)for(int b=a;b<7;b++)for(int c=b;c<7;c++){Mon m{};m[a]++;m[b]++;m[c]++;index[m]=count++;}
Rat DB;readpoly(co,DB.n);vector<fmpq_mpoly_struct>images(9);for(auto&v:images)fmpq_mpoly_init(&v,c9);fmpq_mpoly_gen(&images[0],0,c9);fmpq_mpoly_gen(&images[1],1,c9);for(int i=0;i<7;i++)read9(co,&images[i+2]);fmpq_mpoly_struct*img[9];for(int i=0;i<9;i++)img[i]=&images[i];fmpq_mpoly_t U,V,P,D,G,NN,DD,temp;for(auto p:{U,V,P,D,G,NN,DD,temp})fmpq_mpoly_init(p,c9);int qr,qc;qi>>qr>>qc;assert(qr==7&&qc==28);vector<Mon>qmons;for(int a=0;a<7;a++)for(int b=a;b<7;b++){Mon m{};m[a]++;m[b]++;qmons.push_back(m);}out<<"56 84\n";
for(int i=0;i<7;i++){int n;qi>>n;Row q;for(int k=0;k<n;k++){int j;qi>>j;readpoly(qi,q[j].n);readpoly(qi,q[j].d);}for(int a=0;a<7;a++){Row row;for(auto&[j,c]:q){Mon m=qmons[j];m[a]++;row[index.at(m)]=c;}out<<row.size()<<'\n';for(auto&[j,c]:row){out<<j<<'\n';writepoly(out,c.n);writepoly(out,c.d);}}}
auto start=chrono::steady_clock::now();for(int i=0;i<7;i++){Rat dc,g,q;fmpq_mpoly_one(dc.n,ctx);for(auto&[j,c]:old[i]){assert(fmpq_mpoly_gcd(g.n,dc.n,c.d,ctx));assert(fmpq_mpoly_divides(q.n,c.d,g.n,ctx));fmpq_mpoly_mul(g.n,dc.n,q.n,ctx);fmpq_mpoly_swap(dc.n,g.n,ctx);}fmpq_mpoly_zero(U,c9);fmpq_t c;fmpq_init(c);ulong ex[2],m9[9];for(auto&[j,cj]:old[i]){assert(fmpq_mpoly_divides(q.n,dc.n,cj.d,ctx));fmpq_mpoly_mul(g.n,q.n,cj.n,ctx);for(int k=0;k<7;k++)m9[k+2]=oldmons[j][k];for(long k=0;k<fmpq_mpoly_length(g.n,ctx);k++){fmpq_mpoly_get_term_exp_ui(ex,g.n,k,ctx);m9[0]=ex[0];m9[1]=ex[1];fmpq_mpoly_get_term_coeff_fmpq(c,g.n,k,ctx);fmpq_mpoly_push_term_fmpq_ui(U,c,m9,c9);}}fmpq_mpoly_sort_terms(U,c9);fmpq_mpoly_combine_like_terms(U,c9);assert(fmpq_mpoly_compose_fmpq_mpoly(V,U,img,c9,c9));fmpq_mpoly_pow_ui(q.n,DB.n,3,ctx);fmpq_mpoly_mul(g.n,dc.n,q.n,ctx);lift(D,g.n);assert(fmpq_mpoly_gcd_cofactors(G,NN,DD,V,D,c9));Rat den;unlift(den.n,DD);Row row;for(long k=0;k<fmpq_mpoly_length(NN,c9);k++){fmpq_mpoly_get_term_exp_ui(m9,NN,k,c9);ex[0]=m9[0];ex[1]=m9[1];Mon mon;for(int j=0;j<7;j++)mon[j]=m9[j+2];fmpq_mpoly_get_term_coeff_fmpq(c,NN,k,c9);fmpq_mpoly_push_term_fmpq_ui(row[index.at(mon)].n,c,ex,ctx);}fmpq_clear(c);out<<row.size()<<'\n';for(auto&[j,v]:row){fmpq_mpoly_sort_terms(v.n,ctx);fmpq_mpoly_combine_like_terms(v.n,ctx);fmpq_mpoly_set(v.d,den.n,ctx);v.reduce();out<<j<<'\n';writepoly(out,v.n);writepoly(out,v.d);}out.flush();cerr<<"PURE CUBIC "<<i<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}
for(auto p:{U,V,P,D,G,NN,DD,temp})fmpq_mpoly_clear(p,c9);for(auto&v:images)fmpq_mpoly_clear(&v,c9);}fmpq_mpoly_ctx_clear(c9);fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
